fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the input arrays have the same length,
    // we iterate over both simultaneously, comparing elements.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x != y)
     .collect()
}